  const MOOD = {"yö": "night", "aamu": "morning", "aamupäivä": "late morning", "päivä": "day", "ilta": "evening", "myöhäisilta": "late evening"};

  // sentences with numbers, and generic words (before and after the pieces)
  const hh = (h) => (h.length < 2 ? '0' + h : h);
  const PRE = [
    [/^klo (\d+)\.(\d\d) · (\S+)$/, (m, h, mm, w) => hh(h) + ':' + mm + ' · ' + (MOOD[w] || w)],
    [/^Versio (\S+) klo (\d+)\.(\d\d)$/, (m, d, h, mm) => 'Version ' + d + ' at ' + hh(h) + ':' + mm],
    [/^Versio /, 'Version '],
    [/^Sokkeli (\S+) on (\S+) m ylempänä$/, 'Plinth $1 is $2 m higher'],
    [/(terassin|maan) tasossa/g, (m, w) => 'level with the ' + (w === 'maan' ? 'ground' : 'terrace')],
    [/(\S+ m) (terassin|maan) yläpuolella/g, (m, d, w) => d + ' above the ' + (w === 'maan' ? 'ground' : 'terrace')],
    [/\bAutotalli (?=\d)/g, 'Garage '],
    [/\. Sadevesiliitos on (\S+) noin (\d+) m päässä, ja kun kaadon on oltava vähintään 1:200, putken pohjan pitäisi talon kohdalla olla vähintään (\S+)\. /,
      '. The stormwater connection ($1) is about $2 m away, and since the fall must be at least 1:200, the pipe bottom at the house should be at least $3. '],
  ];
  const POST = [
    [/\bn\. (?=[+−\d-])/g, 'approx. '],
    [/\bnoin (?=[+−\d-])/g, 'approx. '],
  ];

  const STORE = 'ah1-lang', ATTRS = ['title', 'aria-label', 'placeholder', 'alt'];
  const SKIP = { SCRIPT: 1, STYLE: 1, TEXTAREA: 1, NOSCRIPT: 1 };
  let lang = 'fi';
  const norm = (s) => s.replace(/[ \t\r\n\f]+/g, ' ').trim();

  // Finnish number format to English: 1 326,5 -> 1,326.5
  const numbers = (s) => s.replace(/(\d),(\d)/g, '$1.$2').replace(/(\d)[  ](\d{3})(?!\d)/g, '$1,$2');
  const cache = new Map();
  function translate(k){
    let r = EXACT[k];
    if (r !== undefined) return r;
    r = k;
    for (const [re, to] of PRE) r = r.replace(re, to);
    for (const [fi, en] of GLOSS) if (r.includes(fi)) r = r.split(fi).join(en);
    for (const [re, to] of POST) r = r.replace(re, to);
    return numbers(r);
  }
  // text in English; the spaces round it as they were
  function en(text){
    if (typeof text !== 'string' || !text) return text;
    const k = norm(text); if (!k) return text;
    let r = cache.get(k);
    if (r === undefined) { r = translate(k); if (cache.size > 6000) cache.clear(); cache.set(k, r); }
    if (r === k) return text;
    return text.slice(0, text.length - text.trimStart().length) + r + text.slice(text.trimEnd().length);
  }
  const t = (text) => (lang === 'en' ? en(text) : text);

